import json
from pathlib import Path

weeks = {
4: [('tether', 'the range or limit of one’s abilities'), ('ulterior', 'undisclosed'), ('wanton', 'unjustifiably malicious'), ('odium', 'hatred'), ('superfluous', 'excessive; unnecessary'), ('accrue', 'to come to a person or thing by way of gain or increment'), ('lacerate', 'to tear or mangle'), ('demur', 'to hesitate due to doubts'), ('prodigal', 'wasteful'), ('virile', 'masculine; manly'), ('ignominious', 'contemptible; disgraceful'), ('impiety', 'lack of respect')],
5: [('obloquy', 'verbal condemnation or abuse of a person or thing'), ('colloquial', 'having to do with conversation; informal speech'), ('nemesis', 'a person who inflicts just punishment'), ('dearth', 'costliness'), ('effluvium', 'an outflow of vapor of invisible particles; a noxious odor'), ('endemic', 'constantly present in a particular country or locality'), ('esoteric', 'understood by only a chosen few'), ('ethereal', 'very light; airy'), ('exigent', 'calling for immediate attention'), ('travail', '1. very hard work; 2. intense pain or agony'), ('fastidious', 'excessive care or delicacy; painstaking'), ('fatuous', 'lacking in seriousness')],
6: [('feint', 'a fake show intended to deceive'), ('sodden', 'soggy'), ('subsidiary', 'giving a service'), ('sanction', 'to give authoritative permission'), ('impetuous', 'moving with great force'), ('obtrude', 'to force oneself or one’s ideas upon another'), ('ignoble', 'ordinary'), ('laggard', '1. a person who has fallen behind; 2. moving slowly'), ('languid', 'lacking vitality'), ('haggard', 'having a worn look'), ('levity', 'lack of seriousness'), ('bereft', 'to be deprived')],
7: [('repudiate', 'to disown; to deny support for'), ('expedient', 'convenient in obtaining a result'), ('palliate', 'to alleviate or ease pain but not cure'), ('dubious', 'causing doubt'), ('teem', 'to be stocked to overflowing'), ('noisome', 'harmful to health'), ('occult', 'mysterious, beyond the range of ordinary knowledge'), ('oscillate', 'to move back and forth'), ('vouchsafe', 'to grant or give, as a favor or graciousness'), ('substantive', 'existing independently of others'), ('parapet', 'a wall for protection'), ('peremptory', 'that which cannot be denied, or changed; final')],
8: [('platonic', 'not amorous or sensual'), ('enfranchised', 'to free from obligation'), ('quirk', 'a peculiar trait'), ('precarious', 'risky; uncertain'), ('prodigious', 'enormous'), ('pungent', 'sharp and piercing'), ('profusion', 'great wastefulness'), ('propinquity', 'closeness in time or place'), ('virulent', 'poisonous'), ('rampart', 'a defense'), ('redolent', 'sweet-smelling'), ('redundant', 'wordy; repetitive')],
9: [('innocuous', 'harmless'), ('exhume', 'to unearth; to reveal'), ('sedulous', 'working diligently'), ('succinct', 'clearly stated; concise'), ('pious', 'having a religious devotion; sacred'), ('meander', 'wandering aimlessly'), ('zenith', 'the highest point'), ('reprobate', 'to condemn; to reject'), ('surfeit', 'to indulge excessively'), ('diffuse', 'spread out'), ('tumid', 'swollen'), ('tumult', 'a noisy commotion')],
10: [('gamut', 'a complete range'), ('flippant', 'disrespectful'), ('dogmatic', 'making assertions with an arrogant manner'), ('presage', 'a foreshadowing characteristic'), ('skulk', 'to move in a stealthy way'), ('diminutive', 'smaller than average'), ('sundry', 'various; miscellaneous'), ('quandary', '1. a state of uncertainty; 2. difficult situation'), ('attenuate', 'to thin out'), ('harangue', 'to talk excitedly'), ('consecrate', 'to declare sacred'), ('tenacious', 'holding firmly; persistent')],
11: [('flux', 'a continual change'), ('malediction', 'talking negatively about another'), ('trenchant', 'cutting; keen or incisive'), ('eclectic', 'made up of material from various sources'), ('circumspect', 'considering all circumstances'), ('guffaw', 'boisterous laughter'), ('ameliorate', 'to improve or make better'), ('contrite', 'remorseful'), ('derision', 'ridicule'), ('frenetic', 'frenzied'), ('gourmand', 'one who eats heartily'), ('allocate', 'to set aside; to designate; to assign')],
12: [('litigate', 'to involve a lawsuit'), ('paean', 'a song of praise or triumph'), ('quiescence', 'state of being at rest or without motion; stillness'), ('plenary', 'full; entire; absolute'), ('scrupulous', 'making sure all details are perfect'), ('coterie', 'a clique; a group who meets frequently, usually socially'), ('ubiquitous', 'present everywhere'), ('vestige', 'a trace of something that no longer exists'), ('abjure', 'to give up'), ('accolade', 'approving or praising mention'), ('rudimentary', 'elementary'), ('altruism', 'unselfish devotion to the welfare of others')],
13: [('laconic', 'sparing of words; terse; pithy'), ('abstemious', 'sparing in use of food or drinks'), ('voracious', 'greedy in eating'), ('misanthrope', 'a person who hates or distrusts everything'), ('wane', 'to gradually become less; to grow dim'), ('termagant', 'constantly quarrelsome woman; a shrew'), ('perquisite', 'a tip in addition to regular income')],
}
path = Path('data/vocabulary.json')
data = json.loads(path.read_text(encoding='utf-8'))
data['lists'] = [item for item in data['lists'] if item['id'] not in {'mr-trumble-weeks-1-3', *(f'mr-trumble-week-{n}' for n in weeks)}]
for week, items in weeks.items():
    data['lists'].append({'id': f'mr-trumble-week-{week}', 'name': f'Mr.Trumble week {week}', 'description': f'{len(items)} vocabulary words from week {week}', 'words': [{'id': word, 'word': word, 'definition': definition, 'acceptedAnswers': []} for word, definition in items]})
path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
